#!/usr/bin/env Rscript
suppressPackageStartupMessages({library(dplyr);library(tidyr);library(readr);library(ggplot2);library(ggthemes)})
a<-commandArgs(trailingOnly=TRUE);stopifnot(length(a)==2)
b<-read_csv(file.path(a[1],'weights_with_se.csv'),show_col_types=FALSE)
s<-read_csv(file.path(a[2],'weights_with_se.csv'),show_col_types=FALSE)
o<-read_csv(file.path(a[1],'observation_residuals.csv'),show_col_types=FALSE)
c<-b |> select(dataset,year,age_bin,baseline_kg=weight_kg,baseline_model_se=se_kg) |> inner_join(s |> select(dataset,year,age_bin,sensitivity_kg=weight_kg,sensitivity_model_se=se_kg),by=c('dataset','year','age_bin')) |> mutate(change_kg=sensitivity_kg-baseline_kg,change_percent=100*(sensitivity_kg/baseline_kg-1))
stopifnot(nrow(c)==1534)
write_csv(c,'2026/weight-at-age-bts-cv-sensitivity/model_comparison.csv')
c |> filter(age_bin==3,year>=2024) |> write_csv('2026/weight-at-age-bts-cv-sensitivity/age3_comparison.csv')
lines<-bind_rows(c |> transmute(dataset,year,age_bin,mean=baseline_kg,se=baseline_model_se,run='Original CVs'),c |> transmute(dataset,year,age_bin,mean=sensitivity_kg,se=sensitivity_model_se,run='BTS 2025-2026 CVs x2')) |> filter(age_bin==3,year>=2015) |> mutate(dataset=recode(dataset,fishery='Fishery weights',BTS='BTS weights'))
obs<-o |> filter(age_bin==3,year>=2015,is.finite(observed_kg)) |> mutate(dataset=recode(dataset,fishery='Fishery weights',BTS='BTS weights'))
p<-ggplot(lines,aes(year,mean,color=run,fill=run))+geom_ribbon(aes(ymin=pmax(0,mean-1.96*se),ymax=mean+1.96*se),alpha=.12,color=NA)+geom_line(linewidth=.7)+geom_point(data=obs,aes(year,observed_kg),inherit.aes=FALSE,size=1.8,color='black')+facet_wrap(~dataset,ncol=1,scales='free_y')+geom_vline(xintercept=2026.5,linetype=2,color='grey40')+scale_color_manual(values=c('Original CVs'='#333333','BTS 2025-2026 CVs x2'='#0072B2'))+scale_fill_manual(values=c('Original CVs'='#333333','BTS 2025-2026 CVs x2'='#0072B2'))+scale_x_continuous(breaks=2015:2028)+labs(x='Year',y='Age-3 weight (kg)',title='Age-3 sensitivity to recent BTS observation errors',subtitle='Only BTS observation SDs for 2025-2026 are doubled; observed means and fishery inputs are preserved.',caption='Points: unchanged observations. Lines: modeled weights. Ribbons: conditional approximate 95% intervals.\nFishery 2026 weights are predictions without fishery observations; 2027-2028 are forecasts.\nThe dashed line marks the end of assessment year 2026. The original run remains the baseline.',color=NULL,fill=NULL)+theme_few(base_size=11)+theme(legend.position='bottom',plot.caption=element_text(hjust=0,size=8))
ggsave('2026/assets/waa-age3-bts-double-cv-comparison.png',p,width=10,height=8,dpi=180)
ggsave('2026/tables/waa-age3-bts-double-cv-comparison.pdf',p,width=10,height=8,device=cairo_pdf)
